// Build-time only: bundle emitted JavaScript, preserving TypeScript source maps.
// Runtime images execute the resulting JavaScript without a TypeScript loader.
import { readFile, readdir, stat, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { createRequire } from 'node:module';

// Generated by ForkLaunch into the production image. Usage: production-build.mjs PLAN.json
const planPath = path.resolve(process.argv[2] ?? '');
const config = JSON.parse(await readFile(planPath, 'utf8'));
if (!config) throw new Error(`Missing production plan in ${planPath}`);
const root = path.resolve(path.dirname(planPath), config.workspace);
const require = createRequire(path.join(root, 'package.json'));
const { build } = require('esbuild');
const packages = new Map();
for (const relative of config.packages) {
  const directory = path.resolve(root, relative);
  if (!directory.startsWith(`${root}${path.sep}`)) throw new Error('Workspace package escapes build root');
  const manifest = JSON.parse(await readFile(path.join(directory, 'package.json'), 'utf8'));
  if (packages.has(manifest.name)) throw new Error('Duplicate workspace package name');
  const generatedContract = await Promise.any(['.forklaunch-sdk-package.json', '.forklaunch-generated', '.forklaunch-sdk-local'].map(async file => {
    if (!await stat(path.join(directory, file)).then(value => value.isFile(), () => false)) throw new Error('absent');
    return true;
  })).catch(() => false);
  packages.set(manifest.name, { directory, manifest, generatedContract });
}

async function existingFile(file) {
  for (const candidate of [file, `${file}.js`, path.join(file, 'index.js')]) {
    if (await stat(candidate).then(value => value.isFile(), () => false)) return candidate;
  }
  throw new Error(`Compiled JavaScript missing: ${file}`);
}

const usesHyperExpress = [...packages.values()].some(({ manifest }) => manifest.dependencies?.['@forklaunch/hyper-express']);
const workspacePlugin = {
  name: 'compiled-workspace-packages',
  setup(builder) {
    // The published adapter ESM has an extensionless Swagger import. Select its
    // declared CommonJS export, leaving its native/transitive dependencies in
    // their package scope. Its validator must share that module identity for MCP
    // admission (instanceof). No installed package or ESM policy is modified.
    builder.onResolve({ filter: /^@forklaunch\/(?:hyper-express|validator)(?:\/.*)?$/ }, ({ path: specifier, namespace }) => {
      if (!usesHyperExpress) return undefined;
      return namespace === 'hyperexpress-commonjs'
        ? { path: specifier, external: true }
        : { path: specifier, namespace: 'hyperexpress-commonjs' };
    });
    builder.onLoad({ filter: /.*/, namespace: 'hyperexpress-commonjs' }, ({ path: specifier }) => ({
      contents: `module.exports = require(${JSON.stringify(specifier)});`,
      loader: 'js'
    }));
    builder.onResolve({ filter: /^[^./]/ }, async ({ path: specifier }) => {
      const name = specifier.startsWith('@') ? specifier.split('/').slice(0, 2).join('/') : specifier.split('/')[0];
      const member = packages.get(name);
      if (!member) return undefined;
      const subpath = specifier.slice(name.length);
      const exports = member.manifest.exports;
      let entry = subpath ? undefined : member.manifest.main;
      if (typeof exports === 'string' && !subpath) entry = exports;
      else if (exports && typeof exports === 'object') {
        const exported = exports[subpath ? `.${subpath}` : '.'];
        entry = typeof exported === 'string' ? exported : exported?.import ?? exported?.default ?? entry;
      }
      if (!entry || typeof entry !== 'string') throw new Error(`Unsupported compiled workspace export: ${specifier}`);
      const file = path.resolve(member.directory, entry);
      if (!file.startsWith(`${member.directory}${path.sep}`) || (/\.[cm]?tsx?$/.test(file) && !member.generatedContract)) {
        throw new Error(`Workspace export must point to compiled JavaScript: ${specifier}`);
      }
      return { path: await existingFile(file) };
    });
  }
};

async function bundle(options, outfile) {
  await build({
    ...options, outfile, bundle: true, platform: 'node', format: 'esm',
    target: 'node22', packages: 'external', sourcemap: 'linked', sourcesContent: true,
    banner: { js: "import { createRequire as __forklaunchCreateRequire } from 'node:module'; const require = __forklaunchCreateRequire(import.meta.url);" },
    plugins: [workspacePlugin], logLevel: 'warning'
  });
}

for (const process of config.processes) {
  const member = packages.get(process.package);
  if (!member) throw new Error('Process package is not in the TypeScript workspace');
  const output = config.packageOutputs ? path.join(member.directory, "production") : path.resolve(root, config.output, process.directory);
  await mkdir(output, { recursive: true });
  for (const entry of process.entries) {
    if (!['server', 'worker'].includes(entry)) throw new Error('Unsupported process entrypoint');
    await bundle({ entryPoints: [await existingFile(path.join(member.directory, 'dist', `${entry}.js`))] }, path.join(output, `${entry}.mjs`));
  }
  if (!process.database) continue;
  if (!/^[a-z][a-z0-9-]*$/.test(process.database)) throw new Error('Unsupported migration directory');
  const migrationsDirectory = path.join(member.directory, 'dist', `migrations-${process.database}`);
  const files = (await readdir(migrationsDirectory).catch(error => {
    if (error.code === 'ENOENT') return [];
    throw error;
  })).filter(file => /^Migration[A-Za-z0-9_]+\.js$/.test(file)).sort();
  let contents = '// No migration files have been declared.\n';
  if (files.length) {
    const configFile = await existingFile(path.join(member.directory, 'dist/mikro-orm.config.js'));
    const imports = files.map((file, index) => `import { ${path.basename(file, '.js')} as Migration${index} } from ${JSON.stringify(path.join(migrationsDirectory, file))};`).join('\n');
    const migrations = files.map((file, index) => `{name:${JSON.stringify(path.basename(file, '.js'))},class:Migration${index}}`).join(',');
    contents = `${imports}\nimport { MikroORM } from '@mikro-orm/core';\nimport config from ${JSON.stringify(configFile)};\nconst orm = await MikroORM.init({...config, migrations:{...config.migrations,migrationsList:[${migrations}]}});\ntry { await (orm.migrator ?? orm.getMigrator()).up(); } finally { await orm.close(true); }\n`;
  }
  await bundle({ stdin: { contents, resolveDir: member.directory, sourcefile: 'production-migrations.mjs', loader: 'js' } }, path.join(output, 'migrate.mjs'));
}
